// ponytail: contagem de referencias feita em codigo — o LLM erra ao contar linhas de tabela.
// Ajuste TIPOS_MATERIAL se o PDF usar outros rotulos na coluna "Tipo de Material".
const TIPOS_MATERIAL = /^[ \t]*(Livro|Peri[oó]dico|Revista|Artigo|Outros|Site|Manual|Apostila|Norma|Disserta[cç][aã]o|Tese|V[ií]deo|Software|Anais|Cap[ií]tulo|E-?book)\s+\S/gim;
function contarRefs(bloco) {
  return ((bloco || '').match(TIPOS_MATERIAL) || []).length;
}
// start = início do cabeçalho (onde a seção anterior termina), position = início do conteúdo
function findSection(text, pattern) {
  const match = new RegExp(pattern, 'im').exec(text);
  return match ? { start: match.index, position: match.index + match[0].length } : null;
}

// Cabeçalhos ancorados no início da linha (template SIGAA); tolerantes a caixa e à falta de acentos.
// Sem a âncora, "As avaliações..." no meio do texto era tomado como a seção Avaliações.
const sectionDefs = [
  { key: 'ementa', pattern: '^Ementa\\s*:?' },
  { key: 'metodologia', pattern: '^Metodologia\\s*:' },
  { key: 'procedimentos_avaliacao', pattern: '^Procedimentos\\s+de\\s+Avalia[çc][ãa]o(\\s+da\\s+Aprendizagem)?\\s*:?' },
  { key: 'horario_atendimento', pattern: '^Hor[áa]rio\\s+de\\s+Atendimento\\s*:?' },
  { key: 'programa', pattern: '^Programa[ \\t]*$' }, // só marca o fim do horário de atendimento
  { key: 'objetivos', pattern: '^Objetivos?(\\s+Gerais?)?\\s*:' },
  { key: 'conteudo_programatico', pattern: '^Conte[úu]do\\s+Program[áa]tico\\s*:?' },
  { key: 'cronograma', pattern: '^Cronograma' },
  { key: 'avaliacoes', pattern: '^Avalia[çc][õo]es\\s*:?[ \\t]*$' },
  { key: 'referencias', pattern: '^Refer[êe]ncias(\\s+B[áa]sicas|\\s+Bibliogr[áa]ficas)?\\s*:?' }
];

return $input.all().map(item => {
  const text = item.json.text || '';

  const sectionPositions = sectionDefs
    .map(s => {
      const found = findSection(text, s.pattern);
      return found ? { key: s.key, ...found } : null;
    })
    .filter(Boolean)
    .sort((a, b) => a.position - b.position);

  const result = {};
  result.identificacao = text.substring(0, 500).trim();

  for (let i = 0; i < sectionPositions.length; i++) {
    const cur = sectionPositions[i];
    const next = sectionPositions[i + 1];
    const content = text.substring(cur.position, next ? next.start : text.length).trim();

    if (cur.key === 'objetivos') {
      // Aceita "GERAL:", "Objetivo Geral", "ESPECÍFICOS:", "Objetivos Específicos" etc.
      const geralMatch = /(OBJETIVO\s+)?GERAL\s*:?/i.exec(content);
      const espMatch = /(OBJETIVOS?\s+)?ESPEC[ÍI]FICOS?\s*:?/i.exec(content);
      const geralEnd = espMatch ? espMatch.index : content.length;
      result.objetivos_geral = geralMatch
        ? content.substring(geralMatch.index + geralMatch[0].length, geralEnd).trim()
        : (espMatch ? content.substring(0, espMatch.index).trim() : content);
      result.objetivos_especificos = espMatch
        ? content.substring(espMatch.index + espMatch[0].length).trim()
        : '';
    } else {
      result[cur.key] = content;
    }
  }

  const iBas = text.search(/Refer[êe]ncias\s+B[áa]sicas/i);
  const iCom = text.search(/Refer[êe]ncias\s+Complementares/i);
  result.ref_basicas = iBas >= 0 ? contarRefs(text.slice(iBas, iCom > iBas ? iCom : text.length)) : 0;
  result.ref_complementares = iCom >= 0 ? contarRefs(text.slice(iCom)) : 0;

  return { json: result };
});

return $input.all().map((item, index) => {
const sections = item.json;

// Recupera nome e id do arquivo do nó de busca (mantido no lineage do item)
const fileMeta = $('Search files and folders').itemMatching(index)?.json || {};
const fileName = fileMeta.name || 'arquivo_desconhecido';
const fileLink = fileMeta.id ? `https://drive.google.com/file/d/${fileMeta.id}/view` : '';

// Limites maiores para campos que precisam ser lidos por inteiro (ex.: contar referências)
const trunc = (str, max = 1500) => str ? str.substring(0, max) + (str.length > max ? '...' : '') : '(não preenchido)';

// ⚙️ CONFIGURE O MODELO AQUI (ex: qwen2.5:7b, qwen2.5:14b, llama3.2, gemma2)
const OLLAMA_MODEL = 'qwen2.5:7b';

// Schema imposto ao Ollama via "format": garante os campos e enums exatos na resposta
const campos = ['identificacao','ementa','metodologia','procedimentos_avaliacao','objetivos_geral','objetivos_especificos','conteudo_programatico','cronograma','avaliacoes','referencias','horario_atendimento','coerencia'];
const campoSchema = {
  type: 'object',
  properties: {
    status: { type: 'string', enum: ['OK', 'INCOMPLETO', 'AUSENTE'] },
    obs: { type: 'string' }
  },
  required: ['status', 'obs']
};
const formatSchema = {
  type: 'object',
  properties: Object.fromEntries(campos.map(c => [c, campoSchema])),
  required: [...campos, 'status_geral', 'obs_geral']
};
formatSchema.properties.status_geral = { type: 'string', enum: ['OK', 'PENDENTE', 'REPROVADO'] };
formatSchema.properties.obs_geral = { type: 'string' };

const prompt = `Você é um avaliador de planos de ensino de uma instituição de ensino superior brasileira.
Avalie cada campo APENAS com base no texto fornecido abaixo. Não invente informações.
Retorne APENAS um JSON válido, sem texto adicional, sem markdown.
Responda SEMPRE em português brasileiro (pt-BR), inclusive todas as observações.

Status possíveis por campo:
- "AUSENTE": o texto do campo está vazio, é "(não preenchido)" ou não tem nenhuma relação com o campo
- "INCOMPLETO": há conteúdo relacionado, mas não atende às regras do campo
- "OK": o conteúdo atende às regras do campo
IMPORTANTE: se houver texto real e relacionado no campo, NUNCA use AUSENTE — escolha entre OK e INCOMPLETO.

Regras por campo:
- identificacao: OK se contiver nome da instituição, nome do componente curricular (disciplina) e nome do docente. Se faltar qualquer um dos três, INCOMPLETO e diga qual falta.
- ementa: OK se descrever os temas da disciplina em texto corrido com pelo menos 15 palavras.
- objetivos_geral: OK se houver qualquer texto preenchido.
- objetivos_especificos: OK se houver qualquer texto preenchido.
- conteudo_programatico: OK se listar os tópicos ou unidades de conteúdo a serem trabalhados.
- metodologia: OK se descrever COMO as aulas serão conduzidas (ex.: aulas expositivas, práticas, projetos, recursos didáticos).
- procedimentos_avaliacao: OK se descrever os instrumentos de avaliação. NÃO exija menção a interdisciplinaridade.
- cronograma: OK se apresentar datas, semanas ou qualquer distribuição temporal dos conteúdos.
- avaliacoes: OK se indicar as avaliações previstas (instrumentos, datas ou pesos).
- horario_atendimento: OK se informar dia(s) e/ou horário(s) de atendimento ao aluno.
- referencias: NÃO conte nada. Use a CONTAGEM VERIFICADA informada nos dados abaixo. OK somente se houver no mínimo 3 básicas E 5 complementares; caso contrário INCOMPLETO, informando na obs quantas há de cada tipo.
- coerencia: OK se os objetivos, a metodologia e os procedimentos de avaliação forem compatíveis entre si; aponte na obs qualquer contradição encontrada.

Status geral:
- "OK": todos os campos estão OK
- "PENDENTE": um ou mais campos estão INCOMPLETO (e nenhum AUSENTE)
- "REPROVADO": um ou mais campos estão AUSENTE

Formato de retorno (JSON puro):
{
  "identificacao": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "ementa": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "metodologia": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "procedimentos_avaliacao": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "objetivos_geral": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "objetivos_especificos": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "conteudo_programatico": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "cronograma": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "avaliacoes": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "referencias": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "horario_atendimento": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "coerencia": {"status": "OK|INCOMPLETO|AUSENTE", "obs": "observação curta"},
  "status_geral": "OK|PENDENTE|REPROVADO",
  "obs_geral": "resumo geral do plano em 1 frase"
}

DADOS DO PLANO DE ENSINO:

IDENTIFICAÇÃO (início do documento):
${trunc(sections.identificacao, 800)}

EMENTA:
${trunc(sections.ementa)}

METODOLOGIA:
${trunc(sections.metodologia)}

PROCEDIMENTOS DE AVALIAÇÃO:
${trunc(sections.procedimentos_avaliacao)}

OBJETIVOS GERAL:
${trunc(sections.objetivos_geral)}

OBJETIVOS ESPECÍFICOS:
${trunc(sections.objetivos_especificos)}

CONTEÚDO PROGRAMÁTICO:
${trunc(sections.conteudo_programatico, 2500)}

CRONOGRAMA:
${trunc(sections.cronograma, 2500)}

AVALIAÇÕES:
${trunc(sections.avaliacoes)}

HORÁRIO DE ATENDIMENTO:
${trunc(sections.horario_atendimento, 500)}

REFERÊNCIAS (CONTAGEM VERIFICADA — use exatamente estes números):
${sections.ref_basicas} referência(s) básica(s) e ${sections.ref_complementares} complementar(es).`;

return {
    json: {
      fileName,
      fileLink,
      refBasicas: sections.ref_basicas ?? 0,
      refComplementares: sections.ref_complementares ?? 0,
      temObjGeral: !!(sections.objetivos_geral || '').trim(),
      temObjEspecificos: !!(sections.objetivos_especificos || '').trim(),
      ollamaPayload: JSON.stringify({
        model: OLLAMA_MODEL,
        prompt,
        stream: false,
        format: formatSchema,
        keep_alive: '30m',
        // num_ctx 8192: maior prompt medido ~4,4k tokens (+ resposta ~300); 12288 não cabia na GPU de 6 GB
        options: { num_ctx: 8192, num_predict: 1500, temperature: 0.1 }
      }),
      // Payload alternativo para o Google Gemini (ver README, seção "Usar o Gemini")
      geminiPayload: JSON.stringify({
        contents: [{ parts: [{ text: prompt }] }],
        generationConfig: { temperature: 0.1, responseMimeType: 'application/json' }
      })
    }
  };
});

const CAMPOS = ['identificacao','ementa','metodologia','procedimentos_avaliacao','objetivos_geral','objetivos_especificos','conteudo_programatico','cronograma','avaliacoes','referencias','horario_atendimento','coerencia'];

function extrairJson(rawText) {
  const m = (rawText || '').match(/\{[\s\S]*\}/);
  const v = JSON.parse(m ? m[0] : rawText);
  if (!v.status_geral) throw new Error('JSON sem status_geral');
  return v;
}

const out = [];
const items = $input.all();

for (let index = 0; index < items.length; index++) {
  const item = items[index];
  const prep = $('Preparar Prompt').itemMatching(index)?.json || {};
  const fileName = prep.fileName || 'arquivo_desconhecido';
  const fileLink = prep.fileLink || '';

  let validacao = null;
  let ultimoErro = '';

  // Erro reportado pelo nó HTTP (timeout, conexão etc.) — mostra a causa real na planilha
  const errHttp = item.json.error?.message || (typeof item.json.error === 'string' ? item.json.error : '');

  try {
    // Ollama: response.response · Gemini: candidates[0].content.parts[0].text
    const rawText = item.json.response
      || item.json.candidates?.[0]?.content?.parts?.[0]?.text
      || '';
    validacao = extrairJson(rawText);
  } catch (e) {
    ultimoErro = errHttp || e.message;
  }

  if (!validacao) {
    validacao = {
      status_geral: 'ERRO',
      obs_geral: 'Falha ao processar resposta da IA: ' + ultimoErro
    };
  }

  // ponytail: contagem deterministica do node "Separar Texto por Topicos" vence a da IA
  if (validacao.status_geral !== 'ERRO') {
    const nb = prep.refBasicas ?? 0;
    const nc = prep.refComplementares ?? 0;
    const okRef = nb >= 3 && nc >= 5;
    validacao.referencias = {
      status: okRef ? 'OK' : 'INCOMPLETO',
      obs: okRef
        ? `${nb} referências básicas e ${nc} complementares.`
        : `${nb} referências básicas (mín. 3) e ${nc} complementares (mín. 5).`
    };
    // ponytail: objetivo preenchido = OK, qualquer que seja a redacao
    if (prep.temObjGeral) validacao.objetivos_geral = { status: 'OK', obs: 'Objetivo geral preenchido.' };
    if (prep.temObjEspecificos) validacao.objetivos_especificos = { status: 'OK', obs: 'Objetivos especificos preenchidos.' };

    // ponytail: interdisciplinaridade nao reprova — rede de seguranca caso o modelo ainda cobre
    if (validacao.procedimentos_avaliacao?.status === 'INCOMPLETO' && /interdisciplinar/i.test(validacao.procedimentos_avaliacao.obs || '')) {
      validacao.procedimentos_avaliacao = { status: 'OK', obs: 'Instrumentos de avaliacao descritos.' };
    }

    const sts = CAMPOS.map(f => validacao[f]?.status);
    validacao.status_geral = sts.includes('AUSENTE') ? 'REPROVADO'
      : sts.includes('INCOMPLETO') ? 'PENDENTE' : 'OK';
  }

  const s = (field) => validacao[field]?.status || 'ERRO';
  const o = (field) => validacao[field]?.obs || '';

  out.push({
    json: {
      'Arquivo': fileName,
      'Link PDF': fileLink,
      'Data Validação': new Date().toLocaleString('pt-BR'),
      'Status Geral': validacao.status_geral || 'ERRO',
      'Observação Geral': validacao.obs_geral || '',
      'Ementa': s('ementa'),
      'Ementa Obs': o('ementa'),
      'Metodologia': s('metodologia'),
      'Metodologia Obs': o('metodologia'),
      'Proc. Avaliação': s('procedimentos_avaliacao'),
      'Proc. Avaliação Obs': o('procedimentos_avaliacao'),
      'Objetivos Geral': s('objetivos_geral'),
      'Objetivos Geral Obs': o('objetivos_geral'),
      'Objetivos Específicos': s('objetivos_especificos'),
      'Objetivos Específicos Obs': o('objetivos_especificos'),
      'Conteúdo Programático': s('conteudo_programatico'),
      'Conteúdo Programático Obs': o('conteudo_programatico'),
      'Cronograma': s('cronograma'),
      'Cronograma Obs': o('cronograma'),
      'Avaliações': s('avaliacoes'),
      'Avaliações Obs': o('avaliacoes'),
      'Referências': s('referencias'),
      'Referências Obs': o('referencias'),
      'Identificação': s('identificacao'),
      'Identificação Obs': o('identificacao'),
      'Horário Atendimento': s('horario_atendimento'),
      'Horário Atendimento Obs': o('horario_atendimento'),
      'Coerência': s('coerencia'),
      'Coerência Obs': o('coerencia')
    }
  });
}

return out;
